		id = 62021,
		sceneName = 'Origin Forme Giratina',
		sceneName_vn = 'Giratina Hình thái Khởi nguyên',
		sceneName_en = 'Origin Forme Giratina',
		sceneName_th = 'กิราตินารูปแบบดั้งเดิม',
		sceneName_in = 'Giratina Bentuk Origin',
		sceneName_ph = 'Porma ng Pinagmulan Giratina',
